import type { Modelo, Seccion, Tipo } from '../types';

const imagen = (slug: string, alt: string) => ({ src: `/images/catalogo/herramientas/tipo-${slug}.avif`, alt, width: 1600, height: 900, origen: 'ia' as const });
const tipo = (slug: string, nombre: string, lead: string, bloques: Tipo['bloques'], especificacion: Tipo['especificacion'], relacionados: string[] = [], resumen: string[] = [], errores: string[] = [], faq: Tipo['faq'] = []): Tipo => ({
  slug, seccion: 'herramientas', nombre, nombreCard: nombre, title: `${nombre}${nombre.length < 12 ? ': herramienta forestal' : ''} para bombero | México`, description: `${nombre} para bombero: uso operativo, selección, materiales, mantenimiento, resguardo y datos necesarios para cotizar una partida en México.`, lead, bloques, especificacion,
  normas: [{ norma: 'Herramientas manuales', alcance: 'No se publica una norma específica para este tipo; confirma las especificaciones del fabricante en la cotización.' }],
  resumen, errores, faq,
  imagen: imagen(slug, `${nombre} para operación de bomberos`), relacionados,
});

export const seccion: Seccion = {
  slug: 'herramientas', nombre: 'Herramientas', h1: 'Herramientas para bombero: entrada forzada y combate forestal', title: 'Herramientas para bombero | forestal y entrada | México', description: 'Herramientas para bombero de entrada forzada y combate forestal: hachas, Halligan, Pulaski, McLeod y equipo para cotizar con envío a México.', eyebrow: 'Catálogo de herramientas operativas',
  lead: 'La herramienta se selecciona por maniobra, material y compatibilidad con el equipo de protección; no por una silueta genérica.',
  intro: ['Una barra Halligan, un hacha, un gancho o una herramienta forestal cumplen funciones distintas. Antes de pedirlas, identifica la escena, el personal capacitado, el espacio disponible y el equipo que ya acompaña la respuesta. La compra debe distinguir entre entrada forzada, revisión desde una posición segura, construcción de línea y liquidación de puntos calientes.', 'En herramientas manuales no se publica una norma específica para sustituir la revisión del fabricante. Pide material de cabeza, tipo de mango, longitud, peso cuando esté declarado, protección de transporte y condiciones de garantía. También define dónde se guardarán: un mango expuesto a humedad, un filo sin funda o una cabeza floja cambian la disponibilidad del equipo.', 'La inspección inicia antes de cada guardia y continúa después de la intervención. Retira del servicio piezas deformadas, fisuradas, con uniones flojas o mangos astillados. La limpieza debe remover tierra, savia y residuos sin ocultar daño. Una herramienta no reemplaza el análisis de escena, el mando de la operación ni el EPP correspondiente.'],
  grupos: [{ titulo: 'Entrada forzada', tipos: ['hacha-de-bombero', 'barra-halligan', 'gancho-bichero'] }, { titulo: 'Combate forestal', tipos: ['pulaski', 'mcleod', 'rastrillo-forestal', 'batefuego', 'bomba-de-mochila-forestal'] }],
  faq: [{ q: '¿Qué herramienta necesita una unidad?', a: 'Depende de las maniobras autorizadas, el riesgo y el entrenamiento. Define primero el procedimiento operativo.' }, { q: '¿Se pueden pedir herramientas por separado?', a: 'Sí. Indica uso, cantidad y especificaciones para que la cotización distinga cada partida.' }, { q: '¿Cómo se almacenan?', a: 'Limpias, secas, sujetas y con filos o puntas protegidos, de acuerdo con el procedimiento de la corporación.' }],
  hero: { src: '/images/catalogo/herramientas/hero-herramientas.avif', alt: 'Herramientas para entrada forzada y combate forestal' }, leyendaImagenIlustrativa: 'Imagen ilustrativa. La configuración exacta se confirma por escrito en la cotización.',
};

export const tipos: Tipo[] = [
  tipo('hacha-de-bombero', 'Hacha de bombero', 'Hacha manual con cabeza de acero forjado y mango de madera o fibra de vidrio para corte y golpe autorizados; elige la geometría según la maniobra y el soporte de tu unidad.', [
    { h2: 'Hacha de bombero para acceso autorizado', parrafos: ['Cotizamos hachas de bombero para cuerpos de bomberos, brigadas y unidades que requieren corte o golpe dentro de una maniobra autorizada. La cabeza de acero forjado puede llevar filo y punta posterior; elige esa configuración si tu procedimiento pide ambas funciones, o pide una cabeza sin punta cuando el riesgo y el trabajo asignado no la requieran.', 'Con casco, guantes y protección ocular, revisamos si el mango de madera o fibra de vidrio permite extraer el hacha del soporte sin invadir el pasillo. Elige madera si tu programa inspecciona astillas y resequedad, o fibra de vidrio si puedes revisar grietas y aplastamientos; en ambos casos pedimos funda para que el filo viaje protegido.'] },
    { h2: 'Datos de hacha en tu cotización', parrafos: ['En cada partida escribimos hacha de bombero, cabeza con filo y punta cuando corresponda, acero forjado, material de mango, longitud declarada, peso declarado y funda. Pide esos datos por separado para distinguir una herramienta de porte de una de mango largo; así tu orden conserva la geometría que tu cuadrilla puede usar y resguardar.', 'También anotamos soporte, orientación de transporte y cantidad por unidad, porque una cabeza de acero forjado exige una retención que no deje filo ni punta expuestos. Elige un soporte que permita tomar el mango con guantes y deja otra configuración fuera si bloquea casco, mangueras o ERA; en recepción cotejamos cada campo con la orden.'], lista: ['Tipo de cabeza: filo y punta según maniobra', 'Material de cabeza: acero forjado', 'Mango: madera o fibra de vidrio', 'Longitud y peso declarados por fabricante', 'Funda para filo y punta', 'Soporte y orientación dentro de la unidad'] },
    { h2: 'Configuración de hacha que proponemos', parrafos: ['Este catálogo no publica un modelo de hacha de bombero, así que proponemos cabeza de acero forjado, mango de madera o fibra de vidrio, funda y soporte conforme a tu operación. Elige hacha para corte y golpe autorizados; combínala con casco, guantes y protección ocular, y pide barra Halligan si tu maniobra requiere apalancamiento.', 'La ficha publica estatus sin norma específica para herramienta manual de acero y solicita especificación del fabricante. Nosotros cotizamos la configuración escrita y la familia de traje que ya usa tu brigada; si trabajas con traje estructural o forestal, pide probar el radio de giro con ese EPP antes de incluir varias piezas en la orden.'] },
    { h2: 'Errores en pliegos de hacha', parrafos: ['Vemos pliegos que escriben hacha pico sin definir filo, punta, acero forjado ni mango; para evitar recibir una geometría distinta, anota cada campo y la maniobra autorizada. También vemos partidas sin funda; pide funda y soporte cuando la herramienta viaje junto con ERA, mangueras o ropa de protección.', 'Otro error es comprar mango de madera o fibra de vidrio sin confirmar compatibilidad con la cabeza, o pedir hacha para una función de palanca. Nosotros pedimos que tu orden separe hacha y barra Halligan, con materiales y resguardo propios; elige la pieza por función y deja fuera cualquier sustitución basada solo en apariencia.'] },
    { h2: 'Inspección y retiro de hacha', parrafos: ['Antes de guardia revisamos cabeza de acero forjado, filo, punta, ojo, unión y mango de madera o fibra de vidrio. Retira el hacha si la cabeza gira, el filo tiene daño, la punta se deforma, el mango presenta astillas o aparecen grietas; registra material, daño y ubicación para que tu cuadrilla no la reintegre por error.', 'Después de una intervención limpiamos tierra, yeso y humedad para observar filo, corrosión y la unión de acero sin residuos. No compensamos holgura con cinta, cuñas improvisadas ni soldadura; te pedimos separar la herramienta para evaluación técnica. Reintegra solo el hacha seca, íntegra, con funda y soporte que protejan la cabeza durante el traslado.'] }], [{ campo: 'Uso principal', valor: 'Corte y golpe en maniobras autorizadas' }, { campo: 'Materiales', valor: 'Acero forjado; mango de fibra de vidrio o madera según modelo' }, { campo: 'Compra', valor: 'Define cabeza, mango, longitud y resguardo' }], [], ['El hacha de bombero reúne cabeza de acero forjado y mango de madera o fibra de vidrio para corte y golpe autorizados. No hay modelo publicado; proponemos la geometría, funda y soporte según la maniobra de tu brigada.', 'Cotizamos cabeza de acero forjado, mango, longitud declarada, peso declarado, funda y soporte para cada unidad. Escríbenos por WhatsApp con tu maniobra, casco y compartimiento para preparar la partida.']),
  tipo('barra-halligan', 'Barra Halligan', 'La barra Halligan Romak Fire HAC1007 es una herramienta de acero inoxidable para rescate y entrada forzada, con extremos y pico para apalancamiento y 91 cm de largo declarado.', [
    { h2: 'Barra Halligan para entrada forzada', parrafos: ['Cotizamos la barra Halligan para brigadas, cuerpos de bomberos y unidades de rescate que requieren apalancamiento autorizado en una escena real. La Romak Fire HAC1007 declara acero inoxidable, extremos y pico; elige esta geometría si tu procedimiento contempla entrada forzada o rescate, y pide otra herramienta si la partida busca corte o golpe.', 'Antes de incluir una Halligan en tu dotación, revisamos la maniobra, el compartimiento y la coordinación con el hacha. HAC1007 declara 91 cm de largo y 90 cm de extremo a extremo, por lo que pedimos medir el soporte con guantes puestos; elige esta barra si libera sin forzar los extremos y conserva una posición segura dentro de la unidad.'] },
    { h2: 'Partida Halligan escrita en la cotización', parrafos: ['En nuestra cotización escribimos Romak Fire, HAC1007, acero inoxidable, 91 cm, 90 cm de extremo a extremo y 6 lb —3.36 kg— para que tu orden no reciba una barra parecida. Pide funda de puntas y soporte si la barra viajará en cabina; así comparas la misma configuración y no una imagen ilustrativa.', 'También confirmamos que el destino sea rescate y entrada forzada, porque HAC1007 no sustituye una hacha ni define técnicas de escena. Si el soporte no admite 91 cm, proponemos reubicar la herramienta o revisar otra configuración antes de surtir; tu requisición debe conservar marca, código y accesorios para que cada pieza llegue identificable.'], lista: ['Marca: Romak Fire', 'Código: HAC1007', 'Material: acero inoxidable', 'Largo declarado: 91 cm', 'Extremo a extremo: 90 cm', 'Peso declarado: 6 lb —3.36 kg—', 'Uso: rescate y entrada forzada'] },
    { h2: 'Modelo Halligan que surtimos', parrafos: ['Surtimos la Romak Fire HAC1007, barra Halligan de acero inoxidable con extremos y pico para apalancamiento, declarada para rescate y entrada forzada. Combínala con el hacha de tu dotación cuando el procedimiento lo determine, además de casco, guantes y protección ocular; elige el conjunto por la maniobra autorizada, no porque las piezas compartan un soporte.', 'Como el catálogo publica HAC1007 sin norma aplicable, la cotización conserva el estatus sin norma y las medidas 91 cm, 90 cm y 6 lb —3.36 kg—. Te entregamos la configuración escrita para cotejarla con tu unidad; si tu casco, guantes o compartimiento limitan la extracción, pide revisar el montaje antes de emitir la orden.'] },
    { h2: 'Errores frecuentes en órdenes Halligan', parrafos: ['Vemos pliegos que nombran solo una Halligan, omiten HAC1007 y aceptan cualquier longitud; para evitarlo, escribe Romak Fire, acero inoxidable, 91 cm, 90 cm de extremo a extremo y 6 lb —3.36 kg—. También vemos partidas sin funda de puntas, así que pide protección y soporte cuando la barra viaje junto con mangueras o ERA.', 'Otro error es pedir la barra para corte o asumir una certificación que el catálogo no publica. Nosotros pedimos que tu orden indique rescate y entrada forzada, estatus sin norma y extremos con pico para apalancamiento; elige hacha u otra herramienta cuando la operación requiera una función distinta y evita sustituir el modelo por apariencia.'] },
    { h2: 'Inspección, limpieza y retiro Halligan', parrafos: ['Antes de guardia revisamos rectitud, horquilla, pico, extremos y corrosión de la HAC1007; prueba además que el soporte libere los 91 cm sin rozar casco, mangueras o ERA. Retira la barra si hay doblez, punta deformada, abertura anormal o corrosión que altere su geometría, y registra modelo, daño y ubicación para mantener trazabilidad.', 'Después de una intervención, limpia y seca el acero inoxidable para ver impactos y suciedad sin ocultar el estado de los extremos. No endereces con calor ni sueldes una Halligan de 6 lb —3.36 kg—; te pedimos separarla y solicitar evaluación técnica. Reintegra solo la pieza recta, con funda de puntas y retención firme en su soporte.'] }], [{ campo: 'Uso principal', valor: 'Apalancamiento en entrada forzada y rescate' }, { campo: 'Material', valor: 'Acero según modelo' }, { campo: 'Selección', valor: 'Longitud, extremos y método de resguardo' }], ['romak-hac1007'], ['La barra Halligan Romak Fire HAC1007 es de acero inoxidable, mide 91 cm y declara extremos y pico para apalancamiento en rescate y entrada forzada. Surtimos este modelo con estatus sin norma aplicable en el catálogo.', 'Cotizamos HAC1007 con 90 cm de extremo a extremo, 6 lb —3.36 kg—, funda de puntas y soporte cuando tu unidad lo requiere. Escríbenos por WhatsApp con la maniobra, el compartimiento y la cantidad para confirmar la partida.'], ['Aceptar una Halligan sin longitud ni perfil de extremos', 'Enderezar una barra doblada con calor o golpes', 'Comprar un kit sin identificar cada herramienta', 'Montar la barra sin protección para el pico'], [{ q: '¿Qué se revisa primero en una Halligan recibida?', a: 'Rectitud del cuerpo, forma de horquilla, cuña o pala, estado del pico y corrosión. Después comprueba que la barra entra y sale del soporte de la unidad sin que los extremos queden expuestos.' }, { q: '¿La barra Halligan sustituye un hacha?', a: 'No. Sus extremos están destinados al apalancamiento autorizado; el hacha cumple corte o golpe según su cabeza. Si la dotación requiere ambas, la requisición debe nombrarlas, medirlas y sujetarlas como piezas independientes.' }]),
  tipo('gancho-bichero', 'Gancho bichero', 'El gancho bichero combina gancho, punta y asta de acero, madera o fibra de vidrio para alcanzar o jalar en una maniobra autorizada; se compra por longitud, material declarado, resguardo y control con casco y guantes.', [
    { h2: 'Gancho bichero para alcance controlado', parrafos: ['Cotizamos gancho bichero para brigadas que necesitan alcanzar, jalar o revisar desde una posición definida, con gancho, punta y asta de acero como componentes de la misma herramienta. Elige este tipo si tu operación requiere distancia y control; pide una barra Halligan de acero cuando la maniobra sea apalancamiento y no arrastre o revisión.', 'Con tu casco, guantes y protección ocular puestos, revisamos el radio de giro y la longitud declarada de un asta de fibra de vidrio para que no invada pasillos o escaleras. Elige una longitud que entre en el soporte de la unidad y permita trabajar con el mango controlado; pedimos protector de punta cuando viajará junto con mangueras o ERA.'] },
    { h2: 'Datos de cotización del gancho bichero', parrafos: ['Para cotizar escribimos uso de alcance o jalado, longitud total, tipo de gancho, punta, material de asta y soporte. Pide esos campos por partida, pues acero, madera o fibra de vidrio cambian la inspección y el resguardo; tu orden debe decir también si el bichero viaja en cabina o compartimiento.', 'Si el bichero de asta de fibra de vidrio o aluminio se usará con casco, guantes y traje de protección, te pedimos probar extracción y reingreso del soporte antes de surtir varias unidades. Elige funda para la punta y una orientación que evite enganches; así la recepción coteja material declarado, gancho y asta sin confundir el bichero con una barra de entrada.'], lista: ['Uso: alcance, jalado o revisión', 'Longitud total declarada', 'Tipo de gancho y punta', 'Material de asta: acero, madera o fibra de vidrio', 'Protector de punta', 'Soporte y orientación de transporte'] },
    { h2: 'Configuración que proponemos para bichero', parrafos: ['No hay un modelo publicado de gancho bichero en este catálogo, por eso proponemos la configuración según tu operación: gancho, punta, asta de acero y longitud declarada por el fabricante. Combínalo con casco, guantes y protección ocular de la dotación; elige la familia de traje que ya usa tu brigada y evita mezclarlo con una Halligan para una función que no corresponde.', 'La ficha no publica una norma específica para este tipo de herramienta manual, por lo que cotizamos el estatus sin norma y pedimos la especificación de acero, madera o fibra de vidrio del fabricante. Si tu unidad necesita una medida concreta, envíanos el espacio de almacenamiento; te entregamos la partida con soporte y protector definidos, en vez de asumir que cualquier asta cabe.'] },
    { h2: 'Fallos comunes al pedir un bichero', parrafos: ['Vemos órdenes que dicen solo gancho y no nombran longitud, punta ni material de asta de acero; para evitar una sustitución, escribe esos campos y el uso de alcance o jalado. También aparecen bicheros sin funda, así que pide protector de punta y soporte cuando tu unidad comparta gabinete con ERA, ropa de protección o mangueras.', 'Otro error es solicitar el bichero como palanca y omitir una herramienta de acero destinada a entrada forzada. Nosotros pedimos que el pliego separe gancho bichero y barra Halligan de acero, con su función y resguardo propios; elige el gancho para revisión controlada y registra la orientación de transporte para evitar que se enganche al abrir el compartimiento.'] },
    { h2: 'Inspección y retiro del gancho bichero', parrafos: ['Antes de guardia revisamos punta, gancho, asta de acero, uniones y corrosión, y comprobamos que el soporte no deje la punta expuesta. Retira el bichero si el gancho está abierto, la punta doblada, el asta tiene fisuras o el mango presenta astillas; registra el material declarado, daño y ubicación para que tu cuadrilla no lo reintegre por error.', 'Después de una intervención, limpiamos tierra y humedad para inspeccionar acero, madera o fibra de vidrio sin residuos que oculten daño. No uses un asta floja ni endereces un gancho deformado; te pedimos separarlo hasta evaluación técnica. Antes de devolverlo a la unidad, confirma funda, soporte y extracción con guantes, casco y protección ocular.'] }], [{ campo: 'Uso principal', valor: 'Alcance, jalado y revisión controlada' }, { campo: 'Materiales', valor: 'Acero y mango según modelo' }, { campo: 'Compra', valor: 'Define longitud, punta y soporte' }], [], ['El gancho bichero reúne gancho, punta y asta de acero para alcanzar, jalar o revisar desde una posición autorizada. No hay un modelo publicado; proponemos la configuración con acero, madera o fibra de vidrio según la operación.', 'Cotizamos longitud, tipo de gancho, punta, material de asta de acero, protector y soporte para tu unidad. Escríbenos por WhatsApp con la maniobra y el espacio disponible para definir la partida con tu casco, guantes y traje.'], ['Comprar un asta larga sin funda de punta ni soporte', 'Pedir un gancho para apalancar sin definir otra herramienta', 'Guardar el gancho orientado hacia mangueras o ropa de protección'], [{ q: '¿Qué debe incluir una cotización de bichero?', a: 'Uso, longitud total, tipo de gancho, punta, material de asta, protector y soporte. Confirma la especificación del fabricante porque no hay un modelo publicado en esta ficha.' }, { q: '¿Cuándo se retira?', a: 'Cuando la punta o gancho se deforman, el asta presenta fisuras o astillas, o la unión tiene juego. Registra el daño y sepáralo de la dotación.' }]),
  tipo('pulaski', 'Pulaski', 'La Pulaski une hacha y azadón en una cabeza de acero para trabajo forestal; elige esta herramienta cuando tu línea requiere corte y remoción de suelo con el mismo mango.', [
    { h2: 'Pulaski para línea forestal', parrafos: ['Cotizamos Pulaskis para brigadas forestales que alternan corte de vegetación y remoción de suelo en una línea autorizada. Su cabeza de acero reúne hacha y azadón; elige Pulaski si tu cuadrilla necesita ambas acciones, o pide McLeod y rastrillo forestal cuando la tarea priorice hojarasca, dientes o capa superficial.', 'Con traje forestal, casco y guantes, revisamos el balance del mango de madera o fibra de vidrio y el espacio de giro antes de surtir. Elige el material que tu programa puede inspeccionar: madera para astillas y resequedad, fibra de vidrio para grietas y aplastamientos; pide protector de filo para el traslado.'] },
    { h2: 'Partida Pulaski por escrito', parrafos: ['En nuestra cotización anotamos cabeza Pulaski de hacha y azadón, acero, mango de madera o fibra de vidrio, largo declarado, peso declarado, protector y cantidad por cuadrilla. Pide estos campos para que tu orden no reciba un rastrillo o McLeod; elige el largo que puedas usar con traje forestal sin golpear el compartimiento.', 'También incluimos soporte y posición dentro del vehículo para la cabeza de acero, porque el filo y el azadón requieren resguardo propio. Si tu brigada alterna varias herramientas en línea, pide Pulaskis por función y vehículo, no como una cantidad uniforme; nosotros cotejamos protector, cabeza y mango con la configuración aprobada al recibir la partida.'], lista: ['Cabeza: hacha y azadón', 'Material de cabeza: acero', 'Mango: madera o fibra de vidrio', 'Largo y peso declarados por fabricante', 'Protector de filo para traslado', 'Cantidad por cuadrilla y soporte de vehículo'] },
    { h2: 'Configuración Pulaski que surtimos', parrafos: ['No hay modelo Pulaski publicado en este catálogo, por eso proponemos una cabeza de acero con hacha y azadón, mango y protector conforme a tu operación forestal. Elige Pulaski para cortar y remover; combínala con traje forestal, casco y guantes, y agrega McLeod si tu línea necesita raspar y concentrar combustible fino.', 'El catálogo declara estatus sin norma específica para esta herramienta manual de acero y pide confirmar especificaciones con el fabricante. Nosotros dejamos por escrito cabeza, mango y resguardo; si tu unidad transporta otra herramienta forestal, pide comprobar extracción con el EPP puesto antes de asignar la Pulaski al soporte.'] },
    { h2: 'Errores al pedir Pulaskis', parrafos: ['Vemos órdenes que sustituyen Pulaski por rastrillo o McLeod sin nombrar hacha y azadón; para evitarlo, escribe ambas caras, acero, mango y protector. También aparecen herramientas con filo sin resguardo; pide funda y soporte si comparten vehículo con traje forestal, guantes o mochilas.', 'Otro error es elegir solo por peso declarado y omitir largo, balance o compatibilidad del mango con la cabeza de acero. Nosotros pedimos que el pliego separe las funciones de corte, remoción y rastrillado de acero; elige Pulaski cuando correspondan sus dos extremos y deja fuera una cabeza deformada o una configuración que no pueda liberarse con guantes.'] },
    { h2: 'Limpieza y retiro de Pulaski', parrafos: ['Antes de guardia revisamos filo, azadón, cabeza de acero, ojo, cuña y mango de madera o fibra de vidrio. Retira la Pulaski si hay holgura, azadón doblado, corrosión alrededor del ojo, astillas, grietas o torsión; registra material, daño y ubicación para impedir que tu brigada la devuelva a la línea.', 'Después de trabajar con tierra y savia limpiamos ambos extremos para que el desgaste no quede oculto. No fijamos una cabeza floja con cuñas improvisadas ni devolvemos un filo dañado al soporte; te pedimos separarla para evaluación técnica. Reintegra solo la herramienta seca, con geometría íntegra y protector colocado para el transporte.'] }], [{ campo: 'Uso principal', valor: 'Trabajo forestal de línea y remoción' }, { campo: 'Cabeza', valor: 'Hacha y azadón' }, { campo: 'Materiales', valor: 'Acero; mango según modelo' }], [], ['La Pulaski combina hacha y azadón en una cabeza de acero para corte y remoción en línea forestal. No hay modelo publicado; proponemos mango, protector y soporte según la operación de tu brigada.', 'Cotizamos cabeza, mango, largo declarado, peso declarado, protector y cantidad por cuadrilla. Escríbenos por WhatsApp con tu traje forestal, vehículo y tarea de línea para definir la partida.']),
  tipo('mcleod', 'McLeod', 'El McLeod combina dientes de rastrillo y hoja tipo azadón para ordenar combustible vegetal y trabajar suelo superficial; elige esta cabeza cuando tu línea necesita ambas acciones.', [
    { h2: 'McLeod para combustible y suelo', parrafos: ['Cotizamos McLeod para brigadas forestales que deben concentrar hojarasca con dientes de acero y raspar la capa superficial con hoja tipo azadón. Elige McLeod si tu operación combina ambas tareas; pide Pulaski cuando se requiera filo y remoción, o rastrillo forestal cuando solo se moverá combustible ligero.', 'Con traje forestal, casco y guantes, revisamos ancho de cabeza, dientes de acero, hoja y mango frente al soporte de tu vehículo. Elige una configuración que puedas extraer sin golpear mochilas o mangueras y pide material declarado por fabricante; así tu cuadrilla recibe una herramienta de trabajo forestal, no un rastrillo ligero sin hoja.'] },
    { h2: 'Campos McLeod en la orden', parrafos: ['Nuestra cotización identifica McLeod, cabeza de acero con hoja y dientes, material declarado, ancho o dimensiones declaradas, mango, cantidad y punto de resguardo. Pide la cara de hoja y la hilera de dientes en la misma partida; elige el ancho que corresponda a tu línea y deja fuera una descripción genérica de rastrillo.', 'También pedimos soporte que no presione los dientes ni el borde de la hoja de acero, porque ambos deben conservar geometría al viajar. Si tu brigada compra Pulaski, McLeod y rastrillo, escribe función y ubicación de cada uno; nosotros confirmamos que el mango, la cabeza y el resguardo coincidan con la orden antes de entregar.'], lista: ['Tipo: McLeod con hoja y dientes', 'Material y ancho declarados de cabeza', 'Mango y dimensiones declaradas', 'Hilera de dientes y hoja en la partida', 'Cantidad por línea o reserva', 'Soporte que no presione dientes ni borde'] },
    { h2: 'Configuración McLeod que proponemos', parrafos: ['Este catálogo no publica un modelo McLeod, por lo que proponemos cabeza con hoja tipo azadón y dientes de rastrillo, mango y soporte según tu operación. Elige McLeod para combustible fino y suelo superficial; combínalo con traje forestal, casco y guantes, y pide Pulaski si tu tarea incorpora corte.', 'La ficha mantiene estatus sin norma específica y solicita especificación del fabricante para material y dimensiones. Nosotros anotamos esa configuración en tu cotización; si el vehículo lleva rastrillo forestal, pide un soporte distinto que conserve visible la cara de hoja y evite deformar dientes durante el traslado.'] },
    { h2: 'Errores frecuentes de McLeod', parrafos: ['Vemos pliegos que piden un rastrillo cuando necesitan McLeod con hoja y dientes; para evitarlo, escribe ambas caras, ancho declarado, mango y soporte. También llegan partidas con dientes desalineados o casquillo con juego; pide que la recepción revise rectitud y fijación antes de distribuir la herramienta.', 'Otro error es elegir un soporte que oprime la hilera de dientes o usar fuerza extra para compensar una hoja deformada. Nosotros pedimos que tu orden separe McLeod, Pulaski y rastrillo por tarea; elige cada pieza para su función forestal y retira cualquier cabeza que ya no asiente pareja sobre suelo o combustible.'] },
    { h2: 'Revisión y retiro del McLeod', parrafos: ['Antes de guardia revisamos dientes, borde de hoja, casquillo, mango y corrosión en el McLeod. Retira la herramienta si los dientes se tuercen, la hoja se ondula, el casquillo tiene juego o el mango se agrieta; registra el daño y la ubicación para que tu cuadrilla no la asigne por error a la línea forestal.', 'Después de jornada limpiamos tierra de las bases de dientes y secamos la cabeza para ver deformación sin residuos. No enderezamos con golpes una hoja ni devolvemos dientes abiertos al soporte; te pedimos separarla para evaluación técnica. Reintegra solo el McLeod con geometría uniforme, mango firme y resguardo que no presione su cabeza.'] }], [{ campo: 'Uso principal', valor: 'Manejo de combustible vegetal y suelo' }, { campo: 'Cabeza', valor: 'Rastrillo y azadón' }, { campo: 'Compra', valor: 'Define dientes, mango y dimensiones' }], [], ['El McLeod reúne hoja tipo azadón y dientes de rastrillo para combustible vegetal y suelo superficial. No hay modelo publicado; proponemos cabeza, mango y soporte de acuerdo con la línea forestal de tu brigada.', 'Cotizamos el McLeod por hoja de acero, dientes, ancho declarado, mango, cantidad y soporte, sin presión. Escríbenos por WhatsApp con tu traje forestal, vehículo y tarea para definir la configuración.']),
  tipo('rastrillo-forestal', 'Rastrillo forestal', 'El rastrillo forestal mueve hojas, agujas, ramas ligeras y ceniza con dientes para reunir combustible vegetal; elige su configuración por el material de tu línea y el soporte del vehículo.', [
    { h2: 'Rastrillo forestal para combustible fino', parrafos: ['Cotizamos rastrillos forestales para brigadas que reúnen hojas, agujas, ramas ligeras y ceniza durante preparación o liquidación. La cabeza de dientes mueve combustible vegetal sin hoja ancha de McLeod ni filo de Pulaski; elige rastrillo si tu tarea es barrer material ligero, y pide otra cabeza si necesitas raspar suelo o cortar.', 'Con traje forestal, casco y guantes, revisamos tipo de diente, ancho de cabeza y mango frente al área de barrido y el vehículo. Elige dientes adecuados para el combustible predominante y un mango con unión firme; pedimos soporte que oriente las puntas lejos de bolsas de EPP, mangueras y redes de carga.'] },
    { h2: 'Datos de rastrillo en cotización', parrafos: ['En nuestra cotización escribimos rastrillo forestal, material declarado de acero, número o configuración de dientes cuando el fabricante lo publica, ancho de cabeza, tipo y longitud de mango, cantidad y soporte. Pide esos campos por partida para que tu orden no reciba un rastrillo de jardinería; elige la configuración que corresponda a combustible fino de tu cuadrilla.', 'También anotamos orientación de dientes de acero y posición de transporte, porque una cabeza expuesta puede enganchar traje forestal o mangueras. Si compras McLeod o Pulaski junto con rastrillos, pide una función para cada herramienta; nosotros cotejamos dientes, mango y sujeción con lo escrito antes de que tu brigada distribuya la partida.'], lista: ['Tipo: rastrillo forestal para combustible vegetal', 'Material y ancho declarados de cabeza', 'Número o configuración de dientes publicada', 'Tipo y longitud declarada de mango', 'Cantidad por cuadrilla o vehículo', 'Soporte que cubra y oriente los dientes'] },
    { h2: 'Configuración forestal que proponemos', parrafos: ['No hay un modelo de rastrillo forestal publicado en este catálogo, así que proponemos cabeza de dientes de acero, mango y soporte conforme a tu combustible vegetal. Elige esta herramienta para reunir material ligero; combínala con traje forestal, casco y guantes, y pide McLeod si tu operación necesita además hoja para trabajar el suelo.', 'El catálogo declara estatus sin norma específica para este tipo de acero y solicita la especificación del fabricante. Nosotros cotizamos material, dientes y mango por escrito; si tu unidad comparte herramientas de línea, pide comprobar que cada asta entra en su soporte con el EPP puesto antes de emitir la orden.'] },
    { h2: 'Fallos de compra del rastrillo', parrafos: ['Vemos órdenes que sustituyen rastrillo forestal por uno de jardinería sin comparar dientes, cabeza, mango ni sujeción; para evitarlo, escribe esos campos y la función de combustible vegetal. También vemos números de dientes omitidos cuando la configuración está publicada; pide ese dato para cotejar la recepción.', 'Otro error es transportar dientes expuestos o reintegrar una cabeza con piezas rotas. Nosotros pedimos soporte que cubra y oriente las puntas, y registramos la ubicación por vehículo; elige una configuración distinta si engancha EPP y retira el rastrillo cuando no conserva una hilera de dientes firme y alineada.'] },
    { h2: 'Inspección y retiro del rastrillo', parrafos: ['Antes de guardia revisamos dientes completos, firmes y alineados, cabeza, unión y mango del rastrillo forestal. Retira la pieza si hay dientes rotos, puntas irregulares, cabeza desprendida, mango con grietas o unión floja; registra el material, daño y ubicación para que tu cuadrilla no la vuelva a cargar sin revisión.', 'Después de jornada eliminamos tierra, ceniza y humedad de la base de los dientes para observar corrosión y daño. No usamos el rastrillo para golpear ni como palanca, y te pedimos separar cualquier pieza comprometida para evaluación técnica. Reintegra solo la cabeza íntegra, seca y orientada con protección dentro del soporte de la unidad.'] }], [{ campo: 'Uso principal', valor: 'Manejo de combustible vegetal' }, { campo: 'Cabeza', valor: 'Dientes según modelo' }, { campo: 'Compra', valor: 'Material, mango y configuración de dientes' }], [], ['El rastrillo forestal reúne combustible vegetal con dientes y mango configurados para la línea. No hay modelo publicado; proponemos la cabeza, el mango y el soporte según el material que atiende tu brigada.', 'Cotizamos dientes, ancho declarado, mango, cantidad y soporte orientado para tu vehículo. Escríbenos por WhatsApp con tu traje forestal y tarea de barrido para definir la partida.']),
  tipo('batefuego', 'Batefuego', 'El batefuego combina pala flexible y mango para controlar llama baja en combustible vegetal; se cotiza por material, forma, longitud, soporte y la táctica forestal definida por tu cuadrilla.', [
    { h2: 'Batefuego para llama baja forestal', parrafos: ['Cotizamos batefuego para brigadas que requieren contacto controlado con llama baja en combustible vegetal, mediante pala flexible y mango. Elige esta herramienta si tu táctica forestal contempla esa condición; pide otra solución cuando haya viento intenso, combustibles pesados o un frente que exija una respuesta distinta a la pala flexible.', 'Con el traje forestal, guantes y casco de tu cuadrilla, revisamos que la longitud de mango conserve postura y distancia de trabajo. Elige una pala flexible de acero con soporte que no la doble durante traslado; pedimos material y forma declarados para que tu unidad no reciba una pala rígida de excavación por una partida forestal.'] },
    { h2: 'Datos que anotamos para el batefuego', parrafos: ['Nuestra cotización escribe batefuego forestal, material y forma de pala flexible, material y longitud de mango, cantidad y soporte. Pide cada valor por partida y vehículo; así eliges una lámina que conserve contacto uniforme y evitas que el resguardo comprima los bordes mientras comparte gabinete con traje forestal y guantes.', 'También pedimos que tu orden diga aplicación en combustible vegetal y distribución por brigada, porque una cantidad en almacén no asegura cobertura en campo. Si la pala no entra libre en el soporte, proponemos cambiar la ubicación antes de surtir; tu recepción debe comparar mango, pala flexible y fijación con la configuración que quedó escrita.'], lista: ['Aplicación: combustible vegetal', 'Pala flexible: material y forma', 'Mango: material y longitud', 'Cantidad por brigada o vehículo', 'Soporte sin compresión de lámina', 'Fijación entre pala y mango'] },
    { h2: 'Configuración forestal que proponemos', parrafos: ['No hay un modelo publicado de batefuego en este catálogo, por eso proponemos pala flexible de acero, mango y soporte según tu operación forestal. Combínalo con traje forestal, casco y guantes de la brigada; elige el batefuego para llama baja y deja por escrito otra herramienta cuando tu línea requiera mover suelo o combustible con dientes.', 'La ficha no publica una norma específica para el batefuego, por lo que cotizamos estatus sin norma y pedimos la especificación de acero del fabricante. Te entregamos material de pala, material de mango y longitud declarada; si tu cuadrilla necesita distribuir piezas entre vehículos, pide esa asignación para que la lámina no quede concentrada en una sola unidad.'] },
    { h2: 'Errores al ordenar batefuegos forestales', parrafos: ['Vemos pliegos que piden una pala para fuego sin confirmar flexibilidad, material o montaje; para evitarlo, escribe batefuego forestal, pala flexible, mango y soporte. También vemos láminas prensadas entre herramientas, por eso pedimos una ubicación que no doble la pala y una partida separada de las piezas rígidas de excavación.', 'Otro error es ordenar cantidad total sin asignar vehículo o brigada, o presentar el batefuego como herramienta para cualquier frente. Nosotros pedimos que el pliego limite la aplicación a llama baja en combustible vegetal y declare estatus sin norma; elige otra táctica cuando cambien las condiciones, en vez de exigir a la pala una función distinta.'] },
    { h2: 'Limpieza y retiro del batefuego', parrafos: ['Antes de guardia revisamos cortes, rajaduras, bordes separados, deformación y la fijación entre pala flexible y mango. Retira el batefuego si la lámina no recupera forma, hay desprendimiento o el mango queda flojo; registra material, daño y ubicación para que tu brigada no lo devuelva al soporte con una condición que afecte el contacto.', 'Después de una intervención, limpiamos ceniza y tierra con un método compatible con el material de la pala y secamos el mango antes de guardar. No recortes ni endereces a golpes una lámina deformada; te pedimos separarla hasta evaluación. Reintegra solo el batefuego con pala flexible intacta, fijación firme y soporte que no comprima sus bordes.'] }], [{ campo: 'Uso principal', valor: 'Control de llama baja en vegetación' }, { campo: 'Componentes', valor: 'Pala flexible y mango según modelo' }, { campo: 'Selección', valor: 'Condiciones de uso, longitud y resguardo' }], [], ['El batefuego usa pala flexible y mango para contacto controlado con llama baja en combustible vegetal. No hay modelo publicado; proponemos material, forma y longitud según la táctica forestal de tu brigada.', 'Cotizamos pala flexible, mango, fijación, cantidad y soporte sin compresión para tu unidad. Escríbenos por WhatsApp con la aplicación, tu traje forestal y la distribución por vehículo para preparar la partida.'], ['Confundir pala flexible con pala rígida de excavación', 'Transportar la lámina prensada o doblada', 'Recortar una pala deteriorada para seguir usándola', 'Ignorar rajaduras debajo de ceniza adherida'], [{ q: '¿Qué debe pedir una brigada al cotizar batefuegos?', a: 'Material y forma de pala flexible, mango, longitud, cantidad, método de soporte y aplicación forestal. Esos datos permiten evitar una sustitución por pala rígida o una lámina que no cabe en el resguardo previsto.' }, { q: '¿Cuándo se retira la pala?', a: 'Ante corte, rajadura, desprendimiento, deformación permanente o fijación floja. La pala necesita contacto uniforme; no se recupera recortándola, enderezándola a golpes ni manteniéndola prensada en el vehículo.' }]),
  tipo('bomba-de-mochila-forestal', 'Bomba de mochila forestal', 'La bomba de mochila forestal integra depósito, bomba, manguera, boquilla y arnés para aplicación puntual de agua en vegetación; se elige por capacidad declarada, estanqueidad, repuestos y ajuste con traje forestal.', [
    { h2: 'Bomba de mochila para apoyo forestal', parrafos: ['Cotizamos bomba de mochila para brigadas que requieren llevar agua para aplicación puntual en vegetación, con depósito, bomba, manguera, boquilla y arnés. Elige esta configuración si tu estrategia tiene punto de llenado y reabasto; pide una línea de manguera u otra solución cuando el escenario requiera abastecimiento continuo o control fuera de su alcance.', 'Con traje forestal, guantes y casco puestos, revisamos arnés, correas y movilidad en pendiente antes de surtir una partida. Elige una mochila que distribuya la carga y conserve depósito estanco; pedimos capacidad declarada, tipo de bomba y boquilla para que tu orden no reciba solo un depósito sin circuito de descarga.'] },
    { h2: 'Campos de cotización para bomba forestal', parrafos: ['En la cotización anotamos capacidad declarada, depósito, tapa, tipo de bomba, manguera, boquilla, arnés, correas y repuestos compatibles. Pide esos componentes por modelo para que sellos, tapas y mangueras correspondan entre sí; tu partida debe indicar cantidad y punto de llenado, en vez de estandarizar una mochila por apariencia.', 'También confirmamos prueba de estanqueidad, descarga y ajuste del arnés con traje forestal antes de aceptar varias unidades. Si el proveedor no declara la longitud de manguera, dejamos ese dato fuera y pedimos confirmación; elige componentes compatibles y registra su ubicación en vehículo para que una correa o sello no inmovilice el conjunto completo.'], lista: ['Capacidad declarada por fabricante', 'Depósito y tapa', 'Tipo de bomba', 'Manguera y boquilla', 'Arnés y correas', 'Sellos y repuestos compatibles', 'Punto de llenado y reabasto'] },
    { h2: 'Configuración que proponemos para mochila', parrafos: ['No hay un modelo publicado de bomba de mochila forestal en este catálogo, por eso proponemos depósito, bomba, manguera, boquilla y arnés según tu operación. Combínala con traje forestal, casco y guantes de tu brigada; elige esta familia para apoyo puntual de agua y deja por escrito si necesitas refacciones compatibles para cada unidad.', 'La ficha no publica una norma específica para esta bomba, por lo que cotizamos estatus sin norma y solicitamos la información del fabricante. Te entregamos capacidad declarada y componentes identificados; si tu operación requiere varias mochilas, pide un mismo modelo para que tapas, sellos y mangueras de repuesto no dependan de una conexión distinta.'] },
    { h2: 'Errores de compra en mochila forestal', parrafos: ['Vemos órdenes que solicitan una mochila de agua y omiten bomba, boquilla, arnés o manguera; para evitarlo, escribe depósito, tapa, tipo de bomba, circuito de descarga y correas. También aparecen partidas sin sellos compatibles, así que pedimos modelo y repuestos antes de estandarizar equipos entre unidades forestales.', 'Otro error es cotizar capacidad sin punto de llenado, prueba de estanqueidad ni ajuste con traje forestal. Nosotros pedimos que tu pliego indique aplicación puntual en vegetación, estatus sin norma y revisión de descarga; elige otro abastecimiento si la cuadrilla no puede reabastecer la mochila o si el arnés limita su movilidad en pendiente.'] },
    { h2: 'Prueba, limpieza y retiro de mochila', parrafos: ['Antes de guardia revisamos tapa, sellos, conexiones, manguera, bomba, boquilla, arnés y correas, con prueba de estanqueidad y descarga. Retira la unidad si hay fuga, manguera agrietada, bomba irregular, sello fatigado o correa rota; registra capacidad declarada, modelo, daño y ubicación para que tu brigada no la cargue como equipo disponible.', 'Después de una intervención, vaciamos, enjuagamos y secamos depósito, manguera y boquilla según el fabricante; no guardamos agua estancada. Te pedimos sustituir solo con componentes compatibles y repetir la prueba antes de reintegrar la mochila. Conserva el arnés limpio y sin torsión para que el traje forestal, guantes y casco no oculten una correa dañada.'] }], [{ campo: 'Uso principal', valor: 'Aplicación puntual de agua en vegetación' }, { campo: 'Componentes', valor: 'Depósito, bomba, manguera, boquilla y arnés' }, { campo: 'Mantenimiento', valor: 'Prueba de estanqueidad, limpieza y secado' }], [], ['La bomba de mochila forestal reúne depósito, bomba, manguera, boquilla y arnés para aplicación puntual de agua en vegetación. No hay modelo publicado; proponemos capacidad declarada y componentes compatibles según tu operación.', 'Cotizamos depósito, tapa, bomba, manguera, boquilla, arnés, correas y repuestos para tu traje forestal. Escríbenos por WhatsApp con punto de llenado, cantidad y ruta de reabasto para revisar la configuración.'], ['Pedir una mochila sin identificar bomba, boquilla y arnés', 'Guardar agua estancada dentro del depósito', 'Estandarizar sin confirmar sellos o mangueras de repuesto', 'Reintegrar una unidad con fuga o correa dañada'], [{ q: '¿Qué prueba se hace antes de salir con la mochila?', a: 'Una prueba de estanqueidad y descarga conforme al diseño: tapa, sellos, conexiones, manguera, bomba y boquilla. También se ajusta el arnés con el traje forestal para verificar que las correas distribuyan la carga.' }, { q: '¿Qué se debe especificar para reponer una bomba de mochila?', a: 'Modelo compatible, capacidad declarada, tipo de bomba, boquilla, tapa, manguera, arnés y los repuestos requeridos. No basta con pedir un depósito: las conexiones y sellos deben corresponder a la misma configuración.' }]),
];

export const modelos: Modelo[] = [{
  id: 'romak-hac1007', seccion: 'herramientas', tipo: 'barra-halligan', marca: 'Romak Fire', fabricante: 'Romak Fire', nombre: 'Barra Halligan', codigo: 'HAC1007', material: 'Acero inoxidable', peso: '6 lb (3.36 kg)', estatusNorma: 'no-aplica', title: 'Barra Halligan Romak Fire HAC1007 | México', description: 'Barra Halligan Romak Fire HAC1007 de acero inoxidable, 91 cm y 6 lb, para rescate y entrada forzada. Consulta configuración y cotización en México.',
  caracteristicas: ['Extremos y pico para apalancamiento', '91 cm de largo; 90 cm de extremo a extremo', 'Peso declarado de 6 lb (3.36 kg)', 'Para operaciones de rescate y entrada forzada'],
  descripcion: ['Elige la Romak Fire HAC1007 si tu orden requiere una barra Halligan de acero inoxidable para rescate y entrada forzada, con extremos y pico para apalancamiento. Escribe HAC1007, 91 cm de largo, 90 cm de extremo a extremo y 6 lb —3.36 kg—; así cotizamos el modelo identificado y no una barra similar por imagen o nombre.', 'La HAC1007 declara acero inoxidable y un peso de 6 lb —3.36 kg—. Durante la prueba con guantes, casco y protección ocular, revisamos que sus 91 cm entren en el soporte, que los 90 cm de extremo a extremo no rocen el compartimiento y que pico y extremos permanezcan protegidos; elige otro montaje si la extracción exige forzar la barra.', 'Pide la barra con funda de puntas y soporte cuando viajará junto con hacha, mangueras o ERA. Nosotros confirmamos la compatibilidad con tu casco, guantes y el espacio de la unidad; si formará parte de un conjunto de entrada, escribe cada herramienta por separado para que HAC1007 conserve acero inoxidable, dimensiones y accesorios propios en la orden.', 'En operación, la HAC1007 corresponde a rescate y entrada forzada dentro de tu procedimiento autorizado. Antes de aceptar un lote, probamos rectitud, extremos, pico, retención y liberación con guantes, además de cotejar 91 cm, 90 cm de extremo a extremo y 6 lb —3.36 kg— contra la orden; rechaza cualquier variación que cambie soporte o resguardo.', 'El catálogo declara HAC1007 sin norma aplicable, por lo que la presentamos como estatus sin norma, nunca como certificación. Antes y después de una intervención revisamos corrosión, doblez, punta deformada y abertura anormal; retira la barra de acero inoxidable si pierde geometría, registra el daño y solicita evaluación técnica sin calentarla ni soldarla.'],
  faq: [{ q: '¿Cuál es el código del modelo?', a: 'El código publicado es HAC1007. Inclúyelo junto con la marca Romak Fire en la requisición para diferenciar esta barra de Halligan de otras longitudes o geometrías disponibles.' }, { q: '¿De qué material es?', a: 'El material declarado para HAC1007 es acero inoxidable. La recepción debe confirmar ese dato con la identificación del modelo y revisar que el acabado no oculte corrosión, golpes o alteraciones de los extremos.' }, { q: '¿Qué longitud declara?', a: 'El modelo declara 91 cm de largo y 90 cm de extremo a extremo. Conserva ambas medidas en la orden porque sirven para validar el soporte, la holgura del compartimiento y la protección de puntas.' }, { q: '¿Cuál es su peso declarado?', a: 'El peso declarado es 6 lb, equivalente a 3.36 kg. Úsalo para comparar logística y soporte, pero prueba la extracción con guantes y la configuración real de la unidad antes de asignarla.' }, { q: '¿La imagen identifica la configuración final?', a: 'No. La imagen representa el tipo de barra Halligan; la compra debe confirmar por escrito HAC1007, acero inoxidable, dimensiones, extremos y cualquier funda o soporte incluido en la partida.' }, { q: '¿Tiene norma publicada en el catálogo?', a: 'No aplica una norma publicada para esta barra dentro del catálogo. Solicita el modelo, material y dimensiones declaradas, y conserva esos datos como criterio de recepción e inventario institucional.' }],
  imagen: imagen('barra-halligan', 'Imagen ilustrativa de barra Halligan para entrada forzada'), resumen: ['La Romak Fire HAC1007 es una barra Halligan de acero inoxidable para rescate y entrada forzada, con extremos y pico para apalancamiento, 91 cm de largo y 6 lb —3.36 kg— declarados. Elige este modelo si tu orden requiere esa geometría y el soporte libera la barra con guantes.', 'Cotizamos HAC1007 con 90 cm de extremo a extremo, funda de puntas y soporte si tu unidad lo necesita. Escríbenos por WhatsApp con tu configuración de casco, guantes y compartimiento; revisamos que los 91 cm entren sin rozar equipo y confirmamos la partida.'],
}];

Object.assign(seccion, {
  resumenHero: [
    'La compra de herramientas para bombero parte de una tarea delimitada. Entrada forzada, alcance controlado y trabajo de línea en vegetación demandan geometrías, longitudes y métodos de resguardo diferentes; una dotación útil evita duplicar piezas que no cubren la misma maniobra.',
    'El inventario debe dialogar con el vehículo, el EPP, la capacitación y el programa de inspección. Acero forjado, fibra de vidrio y madera requieren cuidados distintos, pero toda herramienta necesita una revisión física, una sujeción de transporte y un criterio claro para retirarla de servicio. En LORICA cotizamos la dotación por maniobra, sin compra mínima.'
  ],
  etiquetas: { menuTipos: 'Herramientas por maniobra', tiposEyebrow: 'Entrada y línea forestal', tiposTitulo: 'Elige por función, no por apariencia', tiposDescripcion: 'Compara alcance, cabeza, mango y forma de resguardo antes de integrar una partida.', elegirTitulo: 'Criterios para equipar una cuadrilla', elegirDescripcion: 'La herramienta correcta depende de la maniobra autorizada, el terreno y el equipo que ya acompaña al personal.', modelosTitulo: 'Modelo disponible', modelosDescripcion: 'Verifica por escrito configuración, dimensiones y accesorios antes de ordenar.' },
  comparativa: { columnas: ['Tipo', 'Uso', 'Referencia', 'Material o forma', 'Ventaja', 'Límite'], filas: [
    ['Hacha de bombero', 'Corte y golpe autorizados', 'Especificación del fabricante', 'Cabeza y mango según modelo', 'Reúne funciones en una pieza', 'No sustituye una palanca ni análisis de escena'],
    ['Barra Halligan', 'Apalancamiento autorizado', 'Especificación del fabricante', 'Barra con extremos y pico', 'Alcance y geometría de entrada', 'Exige control del movimiento y resguardo de puntas'],
    ['Gancho bichero', 'Alcance y revisión', 'Especificación del fabricante', 'Gancho y mango largo', 'Mantiene distancia definida', 'No evalúa estabilidad ni sirve como palanca'],
    ['Pulaski y McLeod', 'Línea y suelo forestal', 'Especificación del fabricante', 'Cabezas combinadas', 'Relacionan vegetación y suelo', 'Requieren separación y lectura de terreno'],
    ['Rastrillo, batefuego y bomba', 'Combustible vegetal y apoyo puntual', 'Especificación del fabricante', 'Dientes, pala o depósito', 'Cubren tareas complementarias', 'No reemplazan una estrategia ni abastecimiento']
  ] },
  criterios: { titulo: 'Cinco decisiones antes de cotizar', items: [
    { termino: 'Maniobra', texto: 'Define la función autorizada y el personal que la realizará.' },
    { termino: 'Geometría', texto: 'Compara cabeza, extremos, longitud y área de movimiento disponible.' },
    { termino: 'Material', texto: 'Elige acero, fibra de vidrio o madera con base en inspección y resguardo.' },
    { termino: 'Transporte', texto: 'Incluye fundas, soportes y protección de filo o punta dentro de la unidad.' },
    { termino: 'Ciclo de vida', texto: 'Establece limpieza, revisión, registro de daño y retiro de servicio.' }
  ] },
  checklistCompra: { titulo: 'Checklist para una partida de herramientas', parrafos: ['Anota función, cantidad, tipo de cabeza o extremo, material de mango, longitud y peso cuando el fabricante lo declare. Describe soporte, funda o protector y el lugar de almacenamiento en cada unidad.', 'Durante la recepción, compara físicamente la configuración solicitada, revisa uniones y acabados, y registra la asignación. Las herramientas de entrada y las forestales se almacenan limpias, secas y sujetas para no dañar a personas ni a otros equipos.'] },
  faq: [
    { q: '¿Qué herramienta cubre entrada forzada?', a: 'La maniobra autorizada define si corresponde hacha, barra Halligan, gancho u otra herramienta; no son equivalentes.' },
    { q: '¿Pulaski y McLeod hacen lo mismo?', a: 'No. Sus cabezas y la relación con suelo o vegetación hacen que cubran trabajos distintos.' },
    { q: '¿Se puede usar madera o fibra de vidrio?', a: 'Ambos materiales se revisan y resguardan de acuerdo con su condición y las indicaciones del fabricante.' },
    { q: '¿Qué debe revisarse antes de una guardia?', a: 'Uniones, deformaciones, corrosión, filos, puntas, mango y el soporte de transporte.' },
    { q: '¿Cuándo se retira una herramienta?', a: 'Ante fisura, holgura, deformación, corrosión relevante o daño que impida conservar su función.' },
    { q: '¿Las herramientas manuales tienen una norma única?', a: 'No se publica una norma específica común para estos tipos; solicita la especificación del fabricante.' },
    { q: '¿Cómo se integra la bomba de mochila?', a: 'Como apoyo definido por la estrategia forestal, con arnés, depósito, manguera y repuestos revisados.' }
  ]
});

const ampliacionesHerramienta: Record<string, Pick<Tipo, 'bloques' | 'errores' | 'faq'>> = {
  'hacha-de-bombero': { bloques: [
    { h2: 'Cabeza, filo y mango de un hacha de bombero', parrafos: ['La cabeza reúne un filo para corte y, cuando el diseño lo incorpora, una punta posterior. Esa geometría concentra masa en un extremo y obliga a revisar el equilibrio con los guantes que usa la dotación. En modelos comunes la cabeza es de acero forjado; el mango puede ser de madera o fibra de vidrio. No son materiales intercambiables en mantenimiento: la madera exige vigilar astillas, cuñas y resequedad; la fibra requiere buscar grietas, delaminación o zonas aplastadas.', 'Una requisición útil separa hacha de mango largo, hacha de porte y hacha con punta. Indica número de piezas, configuración de cabeza, material y longitud de mango, peso si el fabricante lo declara, funda de filo y sistema de sujeción. Cuando se compra para una unidad, anota el compartimiento y orientación de montaje: un filo protegido pero colocado donde el mango no puede extraerse con guantes sigue siendo una mala integración.'] },
    { h2: 'Fallas propias y recepción del hacha', parrafos: ['En recepción comprueba que la cabeza no gire sobre el mango, que el ojo no tenga separación visible y que filo y punta lleguen protegidos. Busca rebabas, golpes en el borde, óxido que oculte picaduras y un mango torcido. Un hacha que rebota por una cabeza floja o que tiene una punta alterada deja de responder de manera previsible; no debe compensarse con cinta, cuñas improvisadas ni soldadura.', 'Después de trabajo con tierra, yeso o humedad, limpia la cabeza y observa el área de unión antes de guardarla. El error de compra frecuente es aceptar una “hacha pico” sin definir cuál extremo se requiere, o adquirirla sin funda ni soporte. También conviene evitar mangos de repuesto sin confirmar compatibilidad con la cabeza adquirida.'], lista: ['Cabeza con filo y punta según la maniobra autorizada', 'Mango de madera o fibra especificado por separado', 'Funda para filo y punta durante el traslado', 'Soporte que permita tomar el mango con guantes'] }
  ], errores: ['Pedir una hacha pico sin definir la geometría de la cabeza', 'Recibir una cabeza que gira o un mango con astillas', 'Guardar el filo sin funda dentro de la cabina', 'Comprar mangos de repuesto sin compatibilidad confirmada'], faq: [{ q: '¿Conviene mango de madera o fibra de vidrio?', a: 'Depende del programa de inspección y del modelo. La madera permite detectar astillas y resequedad; la fibra exige revisar grietas o aplastamientos. En ambos casos, confirma que el mango corresponde a la cabeza solicitada.' }, { q: '¿Qué debe incluir la partida de hachas?', a: 'Cantidad, tipo de cabeza, material y longitud de mango, peso declarado cuando exista, funda para filo o punta y el soporte de la unidad. Así la recepción puede distinguir una herramienta de porte de una de mango largo.' }] },
  'barra-halligan': { bloques: [
    { h2: 'Geometría de la barra Halligan', parrafos: ['Una Halligan no es una barra lisa: reúne horquilla, cuña o pala y pico, según el diseño. Los extremos concentran la carga y dependen de que el cuerpo conserve rectitud. El acero y la longitud se comparan entre barras de la misma familia; una pieza corta ocupa menos espacio, mientras una barra larga cambia alcance, palanca y el soporte que cabe en la unidad.', 'Pide longitud total, material declarado, perfil de extremos, peso declarado si existe y funda o cubierta para puntas. Si trabajará junto con un hacha, registra las dos piezas por separado; comprar un “kit” sin medidas y sin identificar cada componente dificulta reponer una sola barra o revisar que el soporte acepte su geometría.'] },
    { h2: 'Daño que invalida una Halligan', parrafos: ['La inspección se concentra en la alineación del cuerpo, el cierre de la horquilla, la punta del pico y los bordes de trabajo. Una curvatura, punta aplanada, abertura anormal o corrosión profunda altera cómo asienta la herramienta. No se endereza con calor ni se recupera una punta mediante soldadura: esas acciones cambian el material sin un criterio de servicio verificable.', 'El error común es comparar solo el nombre Halligan y omitir longitud o forma de extremos. Otro es fijarla en un compartimiento sin protección de punta; el movimiento del vehículo puede golpear mangueras, ERA o puertas. Recibe cada barra sobre una superficie plana y verifica que el sistema de retención la inmovilice sin presionar los extremos.'], lista: ['Longitud compatible con el compartimiento asignado', 'Extremos identificados: horquilla, cuña o pala y pico', 'Cuerpo recto, sin abertura o doblez visible', 'Funda de puntas y soporte de retención'] }
  ], errores: ['Aceptar una Halligan sin longitud ni perfil de extremos', 'Enderezar una barra doblada con calor o golpes', 'Comprar un kit sin identificar cada herramienta', 'Montar la barra sin protección para el pico'], faq: [{ q: '¿Qué se revisa primero en una Halligan recibida?', a: 'Rectitud del cuerpo, forma de horquilla, cuña o pala, estado del pico y corrosión. Después comprueba que la barra entra y sale del soporte de la unidad sin que los extremos queden expuestos.' }, { q: '¿La barra Halligan sustituye un hacha?', a: 'No. Sus extremos están destinados al apalancamiento autorizado; el hacha cumple corte o golpe según su cabeza. Si la dotación requiere ambas, la requisición debe nombrarlas, medirlas y sujetarlas como piezas independientes.' }] },
  'gancho-bichero': { bloques: [
    { h2: 'Alcance, gancho y asta', parrafos: ['El bichero combina una punta y un gancho montados en un asta; su característica de compra es el alcance, no solo el metal de la cabeza. La longitud debe permitir revisar o jalar desde una posición autorizada sin que el extremo opuesto invada pasillos, escaleras o el perímetro del equipo. El asta puede ser de madera, fibra u otro material declarado por el fabricante.', 'Define si se requiere gancho simple, doble o una geometría concreta, además de longitud total, material de asta, protector de punta y tipo de soporte. No uses la palabra “gancho” como sustituto de esos datos: una diferencia en alcance modifica el radio de giro y puede volver inutilizable un compartimiento diseñado para una pieza más corta.'] },
    { h2: 'Revisión de la punta y del asta', parrafos: ['Antes de asignarlo, observa que la punta conserve su forma, que el gancho no esté abierto y que la cabeza no tenga juego. Recorre el asta buscando fisuras, astillas, humedad atrapada o aplastamientos. Una unión floja puede cambiar el ángulo de tracción y un gancho deformado puede soltar el material sin aviso; ambos son motivos para separarlo de la dotación.', 'Una compra falla cuando se entrega un asta larga sin funda de punta ni soporte. También es incorrecto pedirlo para “apalancar” sin haber definido otra herramienta para ese fin. Guárdalo con el gancho orientado para no enganchar arneses, mangueras o ropa de protección al abrir el compartimiento.'], lista: ['Longitud que cabe en la unidad y en el área de maniobra', 'Tipo de gancho y punta descritos por escrito', 'Asta sin fisuras, astillas ni zonas aplastadas', 'Protector que evite enganches en el vehículo'] }
  ], errores: ['Confundir alcance con capacidad de apalancamiento', 'Aceptar un gancho abierto o una punta doblada', 'No medir el asta frente al soporte de la unidad', 'Dejar el gancho expuesto junto a mangueras o arneses'], faq: [{ q: '¿Cómo se define la longitud del bichero?', a: 'Con el alcance requerido, el radio de giro disponible y el compartimiento donde viajará. Una longitud mayor no es automáticamente mejor: puede impedir el control del asta o bloquear la extracción con guantes.' }, { q: '¿Qué condición obliga a retirarlo?', a: 'Gancho abierto, punta doblada, cabeza floja, asta fisurada, astillada o aplastada. No se debe compensar el daño con cinta ni usar la pieza hasta que exista una evaluación técnica aplicable.' }] },
  pulaski: { bloques: [
    { h2: 'Filo y azadón para línea forestal', parrafos: ['La Pulaski tiene una cabeza combinada: un lado trabaja como hacha y el opuesto como azadón. Esa relación permite cortar vegetación leñosa y remover suelo mineral en la preparación de línea, pero no convierte la herramienta en sustituto de un McLeod para rastrillar ni de un rastrillo para juntar hojarasca. El mango suele ser de madera o fibra de vidrio y su longitud afecta el balance al alternar ambos lados.', 'Para cotizar, declara cabeza Pulaski, material y largo de mango, peso si está publicado, protector de filo y cantidad por cuadrilla o vehículo. El comprador debe indicar que se destina a trabajo forestal, porque una cabeza con dos extremos de trabajo requiere una funda y un soporte que no aplasten el filo ni permitan que el azadón golpee el compartimiento.'] },
    { h2: 'Desgaste de una Pulaski en terreno', parrafos: ['La tierra abrasiva redondea el filo y puede ocultar desgaste en la transición entre cabeza y mango. Revisa cuña o fijación, corrosión alrededor del ojo, azadón doblado y grietas longitudinales en el mango. Si la cabeza se afloja, el cambio de dirección entre corte y remoción aumenta la posibilidad de pérdida de control; la herramienta se separa, no se asegura con una cuña improvisada.', 'Evita comprar Pulaskis por el peso anunciado sin revisar el largo y la geometría de ambos extremos. En recepción coteja que cada protector cubra el filo y que el mango no tenga barniz cuarteado, astillas o torsión. Limpia suelo y savia tras cada jornada para que la inspección posterior no confunda desgaste con suciedad.'], lista: ['Cabeza de hacha y azadón para tareas forestales', 'Mango y fijación revisados en el cambio de extremos', 'Protector que cubra el filo durante traslado', 'Cantidad distribuida por cuadrilla, no solo por almacén'] }
  ], errores: ['Sustituir una Pulaski por un rastrillo o McLeod sin revisar la tarea', 'Aceptar un azadón doblado o cabeza floja', 'Seleccionar solo por peso sin confirmar largo y balance', 'Transportar ambos extremos sin protector ni soporte'], faq: [{ q: '¿Pulaski y McLeod se compran para lo mismo?', a: 'No. La Pulaski corta y remueve con filo y azadón; el McLeod rastrilla combustible fino y trabaja la capa superficial. Una compra de línea forestal debe repartir ambas funciones según el terreno y la táctica.' }, { q: '¿Qué se busca en la unión de cabeza y mango?', a: 'Holgura, cuña salida, corrosión alrededor del ojo, grietas y torsión. La combinación de hacha y azadón cambia el sentido del esfuerzo, por lo que esa unión se revisa antes y después de trabajo en suelo.' }] },
  mcleod: { bloques: [
    { h2: 'Hoja, dientes y mango del McLeod', parrafos: ['El McLeod integra una hoja ancha tipo azadón y una hilera de dientes de rastrillo. La hoja puede raspar la capa superficial; los dientes sirven para concentrar hojarasca, agujas y material ligero. El ancho de cabeza, número y separación de dientes cambian la respuesta en combustible fino, por lo que no conviene especificarlo como un “rastrillo” sin describir la cara de azadón.', 'La orden debe incluir configuración de cabeza, material, ancho o dimensiones declaradas, mango, cantidad y punto de resguardo. Para compras de brigada, define cuántas piezas irán a línea y cuántas quedarán en reserva. Una cabeza ancha requiere espacio para extraerla sin golpear dientes contra gabinetes ni contra otros implementos forestales.'] },
    { h2: 'Inspección de dientes y borde', parrafos: ['Los dientes torcidos reducen el contacto con el material y pueden enganchar raíces o equipo; el borde de la hoja puede deformarse al trabajar suelo pedregoso. Revisa ambos lados de la cabeza, el casquillo y la rectitud del mango. Si la herramienta ya no asienta de forma pareja, exigir más fuerza al usuario no corrige el problema y eleva la fatiga.', 'El error de adquisición más habitual es recibir un rastrillo ligero cuando se pidió un McLeod con hoja. Evita también el soporte que sujeta los dientes con presión y los deforma. Al cerrar jornada, retira tierra de las bases de los dientes, seca la cabeza y guarda el borde orientado para no cortar fundas, mochilas o mangueras.'], lista: ['Cara de hoja y dientes descritas en la misma partida', 'Ancho de cabeza y material declarados', 'Dientes rectos y casquillo sin movimiento', 'Soporte que no presione ni doble la hilera de dientes'] }
  ], errores: ['Pedir un rastrillo cuando se necesita McLeod con hoja', 'Aceptar dientes desalineados o casquillo con juego', 'Elegir soporte que presiona la hilera de dientes', 'Usar fuerza extra para compensar una hoja deformada'], faq: [{ q: '¿Por qué anotar el ancho de la cabeza McLeod?', a: 'Porque el ancho cambia la cobertura sobre suelo y combustible fino, así como el espacio que requiere en el vehículo. La medida declarada evita recibir una cabeza estrecha o un rastrillo que no cumple la misma función.' }, { q: '¿Qué daño es característico del McLeod?', a: 'Dientes torcidos, borde de hoja ondulado y juego en el casquillo. Estos daños alteran el contacto simultáneo con suelo y vegetación; limpia la pieza para verlos y retírala si no conserva su geometría.' }] },
  'rastrillo-forestal': { bloques: [
    { h2: 'Dientes para combustible vegetal fino', parrafos: ['El rastrillo forestal mueve agujas, hojas, ramas ligeras y ceniza; no incorpora la hoja ancha de un McLeod ni el filo de una Pulaski. La forma, longitud y separación de dientes deben responder al combustible predominante: dientes muy cerrados retienen material fino, mientras una configuración distinta puede dejar pasar ramas o acumular tierra.', 'Especifica número o configuración de dientes cuando el fabricante lo publique, ancho de cabeza, material, tipo y longitud de mango, y cantidad por cuadrilla. Añade el soporte de transporte: los dientes deben viajar hacia una zona protegida, sin enganchar la red de carga ni perforar bolsas de EPP.'] },
    { h2: 'Compra y conservación del rastrillo', parrafos: ['Revisa que los dientes estén completos, firmes y alineados; una pieza rota deja una punta irregular que engancha material. Examina la unión con el mango, sobre todo después de barrer terreno con piedra o raíces. No se compra para golpear o abrir paso: su selección se justifica por la acción de reunir y redistribuir combustible ligero.', 'No sustituyas un rastrillo forestal por uno de jardinería sin comparar cabeza, mango y sujeción. La recepción debe contar dientes cuando la configuración es parte de la orden y probar que el asta entra en el soporte. Al limpiar, elimina ceniza húmeda de la base de los dientes para no dejar corrosión escondida.'], lista: ['Configuración de dientes acorde con material fino', 'Cabeza sin dientes rotos ni puntas irregulares', 'Mango y unión adecuados para barrido exterior', 'Soporte que cubra y oriente los dientes'] }
  ], errores: ['Comprar un rastrillo de jardinería como sustituto no comparado', 'Omitir el número o configuración de dientes', 'Dejar dientes expuestos que enganchan EPP', 'Reintegrar una cabeza con dientes rotos'], faq: [{ q: '¿Rastrillo forestal o McLeod para hojarasca?', a: 'El rastrillo forestal se destina a reunir combustible ligero con sus dientes. El McLeod añade una hoja para trabajar la superficie del suelo. La decisión depende de si se necesita barrer material, raspar suelo o ambas acciones.' }, { q: '¿Cómo se recibe una partida de rastrillos?', a: 'Cuenta las piezas y la configuración de dientes solicitada, revisa alineación, unión y mango, y confirma que cada asta tenga soporte. La inspección de recepción debe detectar dientes rotos antes de distribuirlos a cuadrillas.' }] },
  batefuego: { bloques: [
    { h2: 'Pala flexible para llama baja', parrafos: ['El batefuego trabaja por contacto controlado con una pala flexible; su desempeño no depende de tener un borde rígido como una pala de excavación. El material y forma de la pala, la longitud del mango y la unión entre ambos determinan cómo se mueve sobre combustible vegetal bajo. No se selecciona para viento intenso, combustibles pesados o frentes que exijan otra táctica.', 'La requisición debe decir batefuego forestal, material y forma de pala, material y longitud de mango, cantidad y soporte que no doble la lámina. Si la brigada compra varias unidades, distribuye el número por vehículo y no solo por almacén. Una pala deformada por quedar prensada entre herramientas puede perder el contacto uniforme que requiere su función.'] },
    { h2: 'Estado de la pala y del mango', parrafos: ['Revisa cortes, rajaduras, bordes separados, deformación permanente y desprendimiento de la pala. También revisa el cuello, remaches o fijación y cualquier movimiento del mango. La ceniza pegada puede ocultar pequeñas roturas; límpiala con un método compatible con el material antes de determinar si la pala vuelve al soporte.', 'El error de compra propio del batefuego es pedir “pala para fuego” sin confirmar flexibilidad y montaje, o usar una funda rígida que la mantenga doblada. No se debe recortar una pala desgastada para prolongar su uso: cambia superficie de contacto y equilibrio. Mantén el mango seco y la pala sin compresión durante resguardo.'], lista: ['Pala flexible, no una pala rígida de excavación', 'Mango, cuello y fijación sin juego', 'Soporte que evite doblar la lámina', 'Distribución por unidad de respuesta'] }
  ], errores: ['Confundir pala flexible con pala rígida de excavación', 'Transportar la lámina prensada o doblada', 'Recortar una pala deteriorada para seguir usándola', 'Ignorar rajaduras debajo de ceniza adherida'], faq: [{ q: '¿Qué debe pedir una brigada al cotizar batefuegos?', a: 'Material y forma de pala flexible, mango, longitud, cantidad, método de soporte y aplicación forestal. Esos datos permiten evitar una sustitución por pala rígida o una lámina que no cabe en el resguardo previsto.' }, { q: '¿Cuándo se retira la pala?', a: 'Ante corte, rajadura, desprendimiento, deformación permanente o fijación floja. La pala necesita contacto uniforme; no se recupera recortándola, enderezándola a golpes ni manteniéndola prensada en el vehículo.' }] },
  'bomba-de-mochila-forestal': { bloques: [
    { h2: 'Depósito, arnés y circuito de descarga', parrafos: ['La bomba de mochila integra depósito, tapa, arnés, bomba manual o mecanismo declarado, manguera y boquilla. A diferencia de una herramienta de mango, su condición depende de que el depósito permanezca estanco y de que el circuito pueda impulsar agua sin fuga. La capacidad solo se solicita cuando el fabricante la declara; además se debe evaluar el peso cargado frente a caminata, pendiente y punto de reabasto.', 'En la orden anota capacidad declarada, tipo de bomba, boquilla, longitud de manguera si se publica, arnés, correas, repuestos compatibles y cantidad. Si habrá una misma partida en varias unidades, pide que tapas, sellos y mangueras correspondan al mismo modelo. Estandarizar sin confirmar repuestos deja fuera de servicio una mochila completa por una sola correa o empaque.'] },
    { h2: 'Prueba de estanqueidad y mantenimiento', parrafos: ['Antes de cargarla al vehículo, llena y presuriza conforme al diseño para verificar tapa, sellos, conexiones, manguera, bomba y boquilla. Una fuga puede vaciar el depósito, mojar equipo de la unidad y dejar al usuario con carga inútil. Revisa también el arnés con el traje forestal puesto: una correa torcida o hebilla dañada cambia el reparto de peso sobre hombros y espalda.', 'Después de uso, vacía el depósito, enjuaga y seca según la indicación del fabricante; no almacenes agua estancada. El error de compra es pedir una “mochila de agua” sin bomba, boquilla, arnés o refacciones identificadas. Separa cualquier unidad con manguera agrietada, sello fatigado, bomba irregular o correa rota hasta sustituirla con componentes compatibles.'], lista: ['Capacidad declarada y punto de reabasto definidos', 'Depósito, tapa, manguera, bomba y boquilla comprobables', 'Arnés probado con traje forestal', 'Sellos, correas y mangueras de repuesto compatibles'] }
  ], errores: ['Pedir una mochila sin identificar bomba, boquilla y arnés', 'Guardar agua estancada dentro del depósito', 'Estandarizar sin confirmar sellos o mangueras de repuesto', 'Reintegrar una unidad con fuga o correa dañada'], faq: [{ q: '¿Qué prueba se hace antes de salir con la mochila?', a: 'Una prueba de estanqueidad y descarga conforme al diseño: tapa, sellos, conexiones, manguera, bomba y boquilla. También se ajusta el arnés con el traje forestal para verificar que las correas distribuyan la carga.' }, { q: '¿Qué se debe especificar para reponer una bomba de mochila?', a: 'Modelo compatible, capacidad declarada, tipo de bomba, boquilla, tapa, manguera, arnés y los repuestos requeridos. No basta con pedir un depósito: las conexiones y sellos deben corresponder a la misma configuración.' }] }
};

for (const t of tipos) {
  const a = ampliacionesHerramienta[t.slug];
  t.chips = ['Selección por maniobra', 'Inspección física', 'Resguardo seguro'];
  t.normas = [{ norma: `Herramientas manuales: ${t.nombre}`, alcance: `No se publica una norma específica para ${t.nombre.toLowerCase()}; confirma las especificaciones del fabricante en la cotización.` }];
  if (!['hacha-de-bombero', 'barra-halligan', 'gancho-bichero', 'pulaski', 'mcleod', 'rastrillo-forestal', 'batefuego', 'bomba-de-mochila-forestal'].includes(t.slug)) {
    t.bloques.push(...a.bloques);
    t.errores = a.errores;
    t.faq = a.faq;
  }
}

const cierreTecnico: Record<string, Tipo['bloques'][number]> = {
  'hacha-de-bombero': { h2: 'Asignación por unidad y relevo', parrafos: ['Una unidad que lleva hachas debe identificar cuál corresponde a cada soporte y revisar que la funda no se haya perdido durante el relevo. El control no se limita al inventario: confirma que el filo queda apartado de la mano al liberar el seguro y que el mango no queda atrapado por otra herramienta.', 'Cuando se piden varias hachas, la orden debe separar las de intervención de las de reserva. Esa distinción facilita revisar cantidades, fundas y mangos compatibles, y evita que una pieza de porte se entregue por error donde se había previsto una de mango largo.'] },
  'barra-halligan': { h2: 'Compatibilidad del soporte con la barra', parrafos: ['El soporte debe abrazar el cuerpo de la barra sin forzar horquilla, cuña, pala o pico. Antes de comprar varios, presenta la longitud declarada contra el compartimiento y verifica que la liberación no obligue a sujetar un extremo de trabajo. Una retención que vibra desgasta el acabado y puede deformar sus partes más expuestas.', 'En una recepción institucional, asigna ubicación e identificación individual. Así es posible detectar una Halligan faltante, intercambiada por otra longitud o devuelta con una punta dañada. La revisión visual debe hacerse antes de cerrar el compartimiento, no hasta que la barra se requiera en una emergencia.'] },
  'gancho-bichero': { h2: 'Montaje y almacenamiento del bichero', parrafos: ['El soporte del bichero debe sujetar el asta en más de un punto cuando su longitud lo requiera; una sola abrazadera permite vibración y golpea la cabeza contra el compartimiento. Verifica que la funda cubra la punta aun cuando el personal retire el gancho con guantes y que el gancho no roce puertas, mangueras o ERA.', 'Para dotaciones con varias longitudes, etiqueta el soporte y la herramienta con la medida autorizada. Mezclar astas parecidas hace difícil detectar una sustitución y cambia el alcance previsto. La recepción debe probar extracción, reingreso y cierre del gabinete con cada medida solicitada.'] },
  pulaski: { h2: 'Distribución de Pulaskis en la cuadrilla', parrafos: ['Una Pulaski se asigna donde el plan prevé alternar corte de vegetación y remoción de suelo. Antes de solicitar cantidades, cuenta las tareas de línea y evita equipar a toda la cuadrilla con la misma cabeza combinada si también se requieren dientes para combustible fino o hojas anchas para raspar.', 'Identifica cada herramienta con su protector y posición de transporte, sin cubrir la zona de unión entre cabeza y mango. Esa disciplina permite ver una cuña salida o corrosión inicial al abrir el compartimiento. Un mango de reemplazo debe conservar el largo y diseño compatibles con la cabeza publicada.'] },
  mcleod: { h2: 'Cantidad y función en una línea forestal', parrafos: ['El número de McLeod se calcula por las posiciones que requieren raspar y ordenar combustible fino, no por una cantidad uniforme de herramientas. En la requisición distingue McLeod, Pulaski y rastrillo; las tres piezas pueden viajar juntas, pero su cabeza responde a una tarea distinta y requiere un lugar propio.', 'Durante el inventario, deja visible la cara de dientes y la hoja para detectar deformación. No apiles la cabeza bajo objetos pesados ni cuelgues la herramienta por un solo diente. La manera de guardar un McLeod protege tanto la geometría de trabajo como la seguridad de quien abre el compartimiento.'] },
  'rastrillo-forestal': { h2: 'Reparto por combustible y vehículo', parrafos: ['El rastrillo se entrega a posiciones donde se necesita reunir material ligero; su cantidad depende de la anchura de trabajo y de la carga vegetal esperada. Documenta cuántos van en cada vehículo y reserva fundas o espacios donde los dientes no queden enfrentados a bolsas, chaquetones o líneas.', 'Para conservar consistencia, compra cabezas con la misma configuración cuando la cuadrilla necesita barrer un mismo tipo de combustible. Si se aceptan variaciones, anótalas por separado. De ese modo, el responsable puede prever qué pieza lleva dientes más cerrados y no descubre la diferencia hasta la salida al terreno.'] },
  batefuego: { h2: 'Preparación antes de distribuir batefuegos', parrafos: ['Antes de asignar batefuegos, extiende cada pala sobre una superficie plana y confirma que recupera su forma sin rajaduras. Esta revisión es distinta de la de un rastrillo: aquí importa que la lámina flexible conserve la superficie que hace contacto con llama baja y combustible vegetal.', 'Incluye en el control de vehículo la ubicación donde la pala queda libre de dobleces. Si se transportan varios, intercala sus láminas con separación que no comprima los bordes. La orden debe indicar qué unidades recibirán la herramienta para evitar concentrar todas las piezas en una sola brigada.'] },
  'bomba-de-mochila-forestal': { h2: 'Control de agua y refacciones', parrafos: ['La planeación de una bomba de mochila incluye dónde se llenará y quién revisará sellos, tapa y boquilla antes de salida. La capacidad declarada ayuda a dimensionar el traslado de agua, pero no expresa por sí sola la disponibilidad: una manguera incompatible o un arnés roto inmovilizan el conjunto completo.', 'Registra la ubicación de cada mochila, el juego de repuestos compatible y la fecha de su última prueba de estanqueidad. Al recibir varias unidades, comprueba que una tapa, sello o boquilla de reemplazo corresponda al modelo adquirido; mezclar conexiones por apariencia puede producir fugas o impedir la descarga.'] }
};

for (const t of tipos) if (!['hacha-de-bombero', 'barra-halligan', 'gancho-bichero', 'pulaski', 'mcleod', 'rastrillo-forestal', 'batefuego', 'bomba-de-mochila-forestal'].includes(t.slug)) t.bloques.push(cierreTecnico[t.slug]);

seccion.intro.push('Una partida bien definida incluye más que la herramienta. Asigna responsables, ubicación dentro de cada vehículo, protectores de punta o filo y una forma de registrar daño. Al recibir, compara material, configuración y accesorios contra la orden; el control inicial evita integrar piezas que no corresponden a la maniobra prevista.', 'Para sostener la disponibilidad, separa la inspección de la improvisación. Limpieza, secado y resguardo permiten observar la condición; no justifican enderezar, soldar o encintar una pieza comprometida. El reemplazo se decide por el estado físico, las instrucciones del fabricante y el criterio técnico establecido por la corporación.');
seccion.intro.push('La distribución por unidad debe reflejar los escenarios de respuesta y no una lista uniforme para todos los vehículos. Identifica qué herramientas viajan en acceso, cuáles se destinan a línea forestal y cuáles requieren fundas o compartimientos separados. Esta planeación permite realizar inventarios de inicio y cierre de turno sin confundir funciones ni dejar equipo expuesto.');
seccion.faq.push({ q: '¿Qué se registra en la recepción?', a: 'Modelo, cantidad, ubicación, estado físico, accesorios y responsable de la inspección inicial.' }, { q: '¿Por qué incluir soporte en la compra?', a: 'Porque una herramienta sin sujeción puede dañarse, dañar otros equipos o ser inaccesible en traslado.' });

export const data = { seccion, tipos, modelos };
